const { createExtractorFromFile } = require('node-unrar-js');
const fs = require('fs');
const path = require('path');

async function main() {
  const extractor = await createExtractorFromFile({ 
    filepath: '/home/runner/workspace/attached_assets/Ai_web_1780863004607.rar', 
    targetPath: '/tmp/extracted_rar' 
  });

  const list = extractor.getFileList();
  const fileHeaders = [...list.fileHeaders];
  const toExtract = fileHeaders
    .filter(h => !h.name.includes('.git') && !h.name.includes('node_modules'))
    .map(h => h.name);

  const extracted = extractor.extract({ files: toExtract });
  for (const file of extracted.files) {
    if (file.extraction) {
      const outPath = path.join('/tmp/extracted_rar', file.fileHeader.name);
      fs.mkdirSync(path.dirname(outPath), { recursive: true });
      fs.writeFileSync(outPath, file.extraction);
    }
  }
  console.log('Done extracting');
}
main().catch(console.error);
