  const handleBooking = () => {
    if (selectedDay && selectedTime) {
      setIsBooked(true);
      setTimeout(() => {
        navigate(`/contact?date=${encodeURIComponent(selectedDay)}&time=${encodeURIComponent(selectedTime!)}`);
      }, 1500);
