}

/* ── CTA BAND ── */
.cta-band {
  padding: 96px max(22px, calc((100vw - 1180px) / 2));
  text-align: center;
}

.cta-band-inner {
  max-width: 680px;
  margin: 0 auto;
}

.cta-band-inner h2 {
  margin: 12px 0 18px;
  font-family: 'Changa One', sans-serif;
  font-size: clamp(2.2rem, 4vw, 3.5rem);
  font-weight: 400;
  line-height: 1.05;
}

.cta-band-inner > p {
  color: rgba(255, 255, 255, 0.72);
  font-size: 1.05rem;
  line-height: 1.6;
}

.cta-band:not(.section-dark) .cta-band-inner h2 {
  color: var(--black);
}

.cta-band:not(.section-dark) .cta-band-inner > p {
  color: var(--muted);
}

/* ── STATS SECTION ── */
.stats-section {
  background: var(--white);
}

/* ── SERVICE EXTRAS ── */
.service-extras {
  margin-top: 20px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.service-deliverables h4,
.service-timeline h4 {
  margin: 0 0 10px;
  font-size: 0.82rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--green-deep);
}

.service-deliverables ul {
  margin: 0;
  padding: 0 0 0 16px;
  color: var(--muted);
  font-size: 0.88rem;
  line-height: 1.7;
}

.service-timeline p {
  color: var(--muted);
  font-size: 0.9rem;
}

/* ── PROCESS SECTION ── */
.process-section {
  background: var(--white);
}

.process-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.process-step {
  padding: 32px 24px;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: var(--paper);
  position: relative;
  transition: transform 220ms ease, box-shadow 220ms ease, border-color 220ms ease;
}

.process-step:hover {
  transform: translateY(-4px);
  box-shadow: 0 24px 58px rgba(7, 8, 6, 0.09);
  border-color: var(--green-deep);
}

.process-num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 52px;
  height: 52px;
  border-radius: 14px;
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--lime), var(--green));
  color: var(--black);
  font-size: 1.1rem;
  font-weight: 900;
}

.process-step h3 {
  margin: 0 0 12px;
  font-family: 'Changa One', sans-serif;
  font-size: 1.25rem;
  font-weight: 400;
}

.process-step p {
  margin: 0;
  color: var(--muted);
  font-size: 0.92rem;
  line-height: 1.65;
}

/* ── TECH SECTION ── */
.tech-section {
  padding-top: 80px;
  padding-bottom: 80px;
}

.tech-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 48px;
}

.tech-card {
  padding: 28px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.05);
  transition: border-color 220ms ease, background 220ms ease;
}

.tech-card:hover {
  border-color: rgba(173, 255, 53, 0.3);
  background: rgba(173, 255, 53, 0.05);
}

.tech-card h4 {
  margin: 0 0 16px;
  font-size: 0.82rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--lime);
}

.tech-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.tech-tags span {
  padding: 6px 14px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 999px;
  color: rgba(255, 255, 255, 0.8);
  font-size: 0.82rem;
  font-weight: 600;
  transition: background 200ms ease, border-color 200ms ease;
}

.tech-tags span:hover {
  border-color: rgba(173, 255, 53, 0.4);
  background: rgba(173, 255, 53, 0.1);
  color: var(--lime);
}

/* ── PRICING SECTION ── */
.pricing-section {
  background: var(--paper);
}

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
  align-items: start;
}

.pricing-card {
  padding: 36px 32px;
  border: 1px solid var(--line);
  border-radius: 24px;
  background: var(--white);
  position: relative;
  transition: transform 220ms ease, box-shadow 220ms ease;
}

.pricing-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 32px 70px rgba(7, 8, 6, 0.1);
}

.pricing-highlight {
  border-color: var(--green-deep);
  background: linear-gradient(180deg, #f7fff0, var(--white));
  box-shadow: 0 24px 60px rgba(17, 153, 54, 0.12);
  transform: translateY(-8px);
}

.pricing-highlight:hover {
  transform: translateY(-14px);
}

.pricing-badge {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  padding: 6px 18px;
  border-radius: 999px;
  background: linear-gradient(135deg, var(--lime), var(--green));
  color: var(--black);
  font-size: 0.78rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  white-space: nowrap;
}

.pricing-header {
  margin-bottom: 28px;
}

.pricing-header h3 {
  margin: 0 0 16px;
  font-family: 'Changa One', sans-serif;
  font-size: 1.4rem;
  font-weight: 400;
  text-transform: uppercase;
}

.pricing-price {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 14px;
}

.pricing-price strong {
  font-size: 2.8rem;
  font-weight: 900;
  line-height: 1;
  color: var(--black);
}

.pricing-price span {
  color: var(--muted);
  font-size: 0.88rem;
}

.pricing-header p {
  margin: 0;
  color: var(--muted);
  font-size: 0.92rem;
  line-height: 1.55;
}

.pricing-features {
  list-style: none;
  margin: 0 0 32px;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 0.9rem;
  color: var(--black);
  line-height: 1.4;
}

.pricing-features li svg {
  flex: 0 0 auto;
  margin-top: 2px;
  stroke: var(--green-deep);
}

.pricing-card .button {
  width: 100%;
  justify-content: center;
}

/* ── VALUES SECTION ── */
.values-section {
  background: var(--white);
}

.values-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.value-card {
  padding: 36px 32px;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: var(--paper);
  transition: transform 220ms ease, box-shadow 220ms ease, border-color 220ms ease;
}

.value-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 24px 58px rgba(7, 8, 6, 0.08);
  border-color: rgba(17, 153, 54, 0.22);
