  font-size: 2.2rem;
  margin-bottom: 16px;
  line-height: 1;
}

.value-card h3 {
  margin: 0 0 12px;
  font-family: 'Changa One', sans-serif;
  font-size: 1.3rem;
  font-weight: 400;
