.team-role {
  margin: 0 0 14px;
  color: var(--lime);
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.team-bio {
  margin: 0;
  color: rgba(255, 255, 255, 0.6);
  font-size: 0.88rem;
  line-height: 1.6;
}

/* ── TIMELINE ── */
.timeline-section {
  background: var(--white);
}

.timeline {
  position: relative;
  margin-top: 52px;
  padding-left: 50%;
}

.timeline::before {
