/* ── Toast ── */
function Toast({ msg, onHide }: { msg: string; onHide: () => void }) {
  useEffect(() => { const t = setTimeout(onHide, 2800); return () => clearTimeout(t); }, [onHide]);
  return <div className="ad-toast">✓ {msg}</div>;
}

